referenceSolutions.javascript:
export function meetingRoomsIi(intervals            )         {
const events           =[];for(const [s,e] of intervals){events.push([s,1],[e,-1]);}events.sort((a,b)=>a[0]-b[0]||a[1]-b[1]);let active=0,best=0;for(const [,d]of events){active+=d;best=Math.max(best,active);}return best;
}

